"""The notification provider catalog (app/data/notifiers.json, generated by
scripts/notifiers.py with the copy the alerter sends from). A catalog
contact keeps its form fields in notification_channels.config; this checks
them the way the alerter will use them."""

import hashlib
import json
import re
from functools import cache
from pathlib import Path
from typing import Any
from urllib.parse import urlparse

from app.config import settings

PATH = Path(__file__).resolve().parent.parent / "data" / "notifiers.json"
MASK = "••••••••"
MAX_FIELD = 2000


@cache
def catalog() -> dict[str, dict[str, Any]]:
    return {d["type"]: d for d in json.loads(PATH.read_text())}


def enabled() -> bool:
    return settings.CATALOG_CHANNELS


def _host_ok(host: str, allowed: list[str]) -> bool:
    h = host.lower()
    return any(h == a.lstrip(".") or (a.startswith(".") and h.endswith(a)) for a in allowed)


def validate(type_: str, fields: dict[str, str]) -> dict[str, str]:
    """The fields as stored: trimmed, defaults left to the alerter."""
    d = catalog()[type_]
    known = {f["key"]: f for f in d["fields"]}
    unknown = set(fields) - set(known)
    if unknown:
        raise ValueError(f"unknown fields for {d['label']}: {', '.join(sorted(unknown))}")
    out: dict[str, str] = {}
    for key, f in known.items():
        v = str(fields.get(key, "") or "").strip()
        if len(v) > MAX_FIELD:
            raise ValueError(f"{f['label']} is too long")
        if not v:
            if f.get("required") and not f.get("default"):
                raise ValueError(f"{f['label']} is required")
            continue
        if v == MASK:
            raise ValueError(f"enter {f['label']} itself")
        if f.get("options") and v not in [o[0] for o in f["options"]]:
            raise ValueError(f"{f['label']} is one of {', '.join(o[0] for o in f['options'])}")
        if f.get("pattern") and not re.fullmatch(f["pattern"], v):
            raise ValueError(f"{f['label']} doesn't look right")
        if f.get("url"):
            u = urlparse(v)
            schemes = {"https"} if settings.ENVIRONMENT == "production" else {"https", "http"}
            if f.get("hosts"):
                if u.scheme != "https" or not u.hostname or not _host_ok(u.hostname, f["hosts"]):
                    raise ValueError(
                        f"{f['label']} must be the URL {d['label']} gave you "
                        f"(https://{f['hosts'][0].lstrip('.')}/…)"
                    )
            elif u.scheme not in schemes or not u.hostname:
                raise ValueError(f"{f['label']} must be a {' or '.join(sorted(schemes))} URL")
        if any(c in v for c in "\r\n\x00") and f.get("url"):
            raise ValueError(f"{f['label']} can't contain line breaks")
        out[key] = v
    return out


def target_for(type_: str, fields: dict[str, str]) -> str:
    """Stable per destination, so the same contact can't be added twice."""
    digest = hashlib.sha256(json.dumps(fields, sort_keys=True).encode()).hexdigest()[:20]
    return f"{type_}:{digest}"


def masked(type_: str, fields: dict[str, str]) -> dict[str, str]:
    secret = {f["key"] for f in catalog()[type_]["fields"] if f.get("secret")}
    return {k: (MASK if k in secret and v else v) for k, v in fields.items()}


def describe(type_: str, fields: dict[str, str]) -> str:
    """What the contacts list shows: the non-secret fields that say where."""
    d = catalog()[type_]
    parts = []
    for f in d["fields"]:
        v = fields.get(f["key"])
        if not v or f.get("secret") or f.get("options"):
            continue
        if f.get("url"):
            v = urlparse(v).hostname or v
        parts.append(v)
    return " · ".join(parts[:2]) or d["label"]


def unmask(type_: str, fields: dict[str, str], old: dict[str, str]) -> dict[str, str]:
    return {k: (old.get(k, "") if v == MASK else v) for k, v in fields.items()}
